import { prisma } from "@/lib/prisma";
import { getApiUser, handleError, ok, readJson, unauthorized, badRequest } from "@/lib/api";
import { parseCsv, validateLeadRow, type ImportPreviewRow } from "@/lib/csv";
import { z } from "zod";

const schema = z.object({
  csv: z.string().min(1),
  mappings: z.record(z.string(), z.string()),
  // Optional explicit row selection (subset of preview indices).
  include: z.array(z.number()).optional(),
});

export async function POST(req: Request) {
  try {
    const user = await getApiUser();
    if (!user) return unauthorized();
    const body = await readJson(req);
    const d = schema.parse(body);

    let records: Array<Record<string, string>>;
    try {
      records = parseCsv(d.csv);
    } catch (err) {
      return badRequest("Couldn't parse CSV: " + (err instanceof Error ? err.message : "invalid format"));
    }

    const targetFields = ["name", "email", "companyOrChannel", "websiteUrl", "youtubeUrl", "niche", "followersCount"] as const;
    const existing = new Set(
      (await prisma.lead.findMany({ where: { userId: user.id, email: { not: null } }, select: { email: true } }))
        .map((l) => (l.email as string).toLowerCase()),
    );

    let rows: Array<ImportPreviewRow & { raw: Record<string, string> }> =
      records.map((record) => {
        const raw: Record<string, string> = {};
        for (const target of targetFields) {
          const header = d.mappings?.[target];
          if (header) raw[target] = record[header] ?? "";
        }
        const row = validateLeadRow(raw, existing) as ImportPreviewRow & { raw: Record<string, string> };
        if (row.email && row.isValid) existing.add(row.email);
        return row;
      });

    if (d.include && d.include.length > 0) {
      rows = rows.filter((_, i) => d.include!.includes(i));
    }

    const valid = rows.filter((r) => r.isValid);
    const invalid = rows.filter((r) => !r.isValid);

    const results = await prisma.lead.createMany({
      data: valid.map((r) => ({
        userId: user.id,
        name: r.values.name || "Unnamed",
        companyOrChannel: r.values.companyOrChannel || "",
        email: r.email || null,
        websiteUrl: r.values.websiteUrl?.trim() || null,
        youtubeUrl: r.values.youtubeUrl?.trim() || null,
        niche: r.values.niche?.trim() || null,
        followersCount: parseCount(r.values.followersCount),
        status: "New",
      })),
    });

    return ok({
      imported: results.count,
      skipped: valid.length - results.count,
      invalid: invalid.length,
      invalidReasons: invalid.slice(0, 10).map((r) => r.reasons),
    });
  } catch (err) {
    return handleError(err);
  }
}

function parseCount(v: string | undefined): number | null {
  if (!v) return null;
  const n = Number(v.replace(/[^0-9]/g, ""));
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : null;
