import { prisma } from "@/lib/prisma";
import { getApiUser, handleError, ok, readJson, unauthorized, badRequest } from "@/lib/api";
import { parseCsv, validateLeadRow } from "@/lib/csv";
import { z } from "zod";

const schema = z.object({
  csv: z.string().min(1),
  mappings: z.record(z.string(), z.string()).optional(),
});

export async function POST(req: Request) {
  try {
    const user = await getApiUser();
    if (!user) return unauthorized();
    const body = await readJson(req);
    const d = schema.parse(body);

    let records: Array<Record<string, string>>;
    try {
      records = parseCsv(d.csv);
    } catch (err) {
      return badRequest("Couldn't parse CSV: " + (err instanceof Error ? err.message : "invalid format"));
    }
    if (records.length === 0) return badRequest("CSV contains no rows");

    // Headers union, in the order they first appear.
    const headers: string[] = [];
    const seenHeaders = new Set<string>();
    for (const r of records) {
      for (const k of Object.keys(r)) {
        if (!seenHeaders.has(k)) {
          seenHeaders.add(k);
          headers.push(k);
        }
      }
    }

    // Resolve mapping: default to same-name mapping.
    const targetToHeader: Record<string, string> = {};
    const targetFields = ["name", "email", "companyOrChannel", "websiteUrl", "youtubeUrl", "niche", "followersCount"] as const;
    for (const f of targetFields) {
      const mapped = d.mappings?.[f];
      if (mapped) {
        targetToHeader[f] = mapped;
      } else if (headers.includes(f)) {
        targetToHeader[f] = f;
      }
    }

    // Existing emails for dup detection.
    const db = await prisma.lead.findMany({ where: { userId: user.id, email: { not: null } }, select: { email: true } });
    const existing = new Set(db.map((l) => (l.email as string).toLowerCase()));

    const preview = records.slice(0, 200).map((record) => {
      const raw: Record<string, string> = {};
      for (const [target, header] of Object.entries(targetToHeader)) {
        raw[target] = record[header] ?? "";
      }
      const row = validateLeadRow(raw, existing);
      if (row.email && row.isValid) existing.add(row.email);
      return row;
    });

    return ok({ headers, mapping: targetToHeader, total: records.length, preview });
  } catch (err) {
    return handleError(err);
  }
