"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { api } from "@/lib/client";
import { ScoreBadge } from "@/components/ScoreBadge";
import { StatusPill } from "@/components/StatusPill";
import { formatDate } from "@/lib/utils";

type Lead = {
  id: string;
  name: string;
  companyOrChannel: string;
  email: string | null;
  niche: string | null;
  leadScore: number;
  scoreBreakdown: unknown;
  status: string;
  createdAt: string;
};

export default function LeadsPage() {
  const [leads, setЛиды] = useState<Lead[]>([]);
  const [q, setQ] = useState("");
  const [tier, setTier] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [importOpen, setImportOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await api<{ leads: Lead[] }>("/api/leads");
      setЛиды(res.leads);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Не удалось загрузить данные");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const filtered = useMemo(() => {
    const query = q.toLowerCase();
    return leads.filter((l) => {
      if (tier) {
        const inTier = tier === "HOT" ? l.leadScore >= 80 : tier === "WARM" ? l.leadScore >= 50 && l.leadScore < 80 : l.leadScore < 50;
        if (!inTier) return false;
      }
      if (query && !`${l.name} ${l.companyOrChannel} ${l.email ?? ""} ${l.niche ?? ""}`.toLowerCase().includes(query)) return false;
      return true;
    });
  }, [leads, q, tier]);

  return (
    <div>
      <div className="page-head">
        <div>
          <h1 className="page-title">Лиды</h1>
          <p className="page-sub">{leads.length} prospects in your pipeline</p>
        </div>
        <div className="row">
          <button className="btn" onClick={() => setImportOpen((v) => !v)}>Import CSV</button>
          <Link href="/leads/new" className="btn btn-primary">+ Add Lead</Link>
        </div>
      </div>

      {importOpen && <ImportWizard onDone={load} onClose={() => setImportOpen(false)} />}

      <div className="row" style={{ marginBottom: 16 }}>
        <input className="input" placeholder="Search leads…" value={q} onChange={(e) => setQ(e.target.value)} style={{ maxWidth: 280 }} />
        <select className="select" value={tier} onChange={(e) => setTier(e.target.value)} style={{ maxWidth: 150 }}>
          <option value="">All scores</option>
          <option value="HOT">🔥 HOT</option>
          <option value="WARM">🟡 WARM</option>
          <option value="COLD">⚪ COLD</option>
        </select>
      </div>

      {error && <div className="small" style={{ color: "var(--red)", marginBottom: 12 }}>{error}</div>}

      {loading ? (
        <div className="card empty">Загрузка лидов…</div>
      ) : filtered.length === 0 ? (
        <div className="card empty">
          {leads.length === 0
            ? <>Your pipeline is empty. Import your first 50 prospects to get started.</>
            : "No leads match your filters."}
        </div>
      ) : (
        <div className="card" style={{ overflow: "hidden" }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>Score</th><th>Name</th><th>Channel</th><th>Email</th><th>Niche</th><th>Status</th><th>Added</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((l) => (
                <tr key={l.id}>
                  <td><ScoreBadge score={l.leadScore} /></td>
                  <td><Link href={`/leads/${l.id}`} style={{ fontWeight: 600 }}>{l.name}</Link></td>
                  <td className="muted">{l.companyOrChannel || "—"}</td>
                  <td className="muted">{l.email ?? "—"}</td>
                  <td className="muted">{l.niche || "—"}</td>
                  <td><StatusPill status={l.status} /></td>
                  <td className="muted small">{formatDate(l.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
function ImportWizard({ onDone, onClose }: { onDone: () => void; onClose: () => void }) {
  const [csv, setCsv] = useState("");
  const [mapping, setMapping] = useState<Record<string, string>>({});
  const [headers, setHeaders] = useState<string[]>([]);
  type PreviewRow = { isValid: boolean; reasons: string[]; values: Record<string, string> };
  const [preview, setPreview] = useState<PreviewRow[]>([]);
  const [state, setState] = useState("paste");

  const runPreview = async () => {
    const res = await api<{ headers: string[]; mapping: Record<string, string>; preview: PreviewRow[]; total: number }>("/api/leads/import/preview", {
      method: "POST", body: JSON.stringify({ csv, mappings: mapping }),
    });
    setHeaders(res.headers);
    setMapping(res.mapping);
    setPreview(res.preview);
    setState("preview");
  };

  const commit = async () => {
    const res = await api<{ imported: number; skipped: number; invalid: number }>("/api/leads/import/commit", {
      method: "POST", body: JSON.stringify({ csv, mappings: mapping }),
    });
    alert(`Imported ${res.imported} lead(s)${res.skipped ? `, skipped ${res.skipped} duplicates` : ""}${res.invalid ? `, ${res.invalid} invalid row(s)` : ""}.`);
    onDone();
    onClose();
  };

  return (
    <div className="card" style={{ padding: 20, marginBottom: 20 }}>
      <div className="row" style={{ marginBottom: 12 }}>
        <strong>Import leads from CSV</strong>
        <button className="btn btn-sm" onClick={onClose}>Close</button>
      </div>

      {state === "paste" && (
        <>
          <textarea
            className="input"
            rows={6}
            placeholder={"name,email,companyOrChannel,niche,followersCount\nAlex Rivera,alex@example.com,ALEX RIVERA,Podcast,84000"}
            value={csv}
            onChange={(e) => setCsv(e.target.value)}
          />
          <div className="row" style={{ marginTop: 12 }}>
            <button className="btn btn-primary" disabled={!csv.trim()} onClick={runPreview}>Preview & map columns</button>
          </div>
        </>
      )}

      {state === "preview" && (
        <>
          <div className="section-label" style={{ marginTop: 8 }}>Column mapping</div>
          <div className="stack" style={{ marginBottom: 12 }}>
            {["name", "email", "companyOrChannel", "niche", "followersCount", "youtubeUrl"].map((target) => (
              <div key={target} className="row">
                <label style={{ width: 160 }}>{target}</label>
                <select className="select" value={mapping[target] ?? ""} onChange={(e) => setMapping((m) => ({ ...m, [target]: e.target.value }))}>
                  <option value="">— none —</option>
                  {headers.map((h) => <option key={h} value={h}>{h}</option>)}
                </select>
              </div>
            ))}
          </div>

          <div className="section-label">Preview ({preview.length} shown)</div>
          <div className="stack" style={{ maxHeight: 200, overflow: "auto", marginBottom: 16 }}>
            {preview.map((row, i) => (
              <div key={i} className="small" style={{ padding: "6px 10px", borderRadius: 6, background: row.isValid ? "var(--green-bg)" : "var(--red-bg)" }}>
                <strong>{row.values.name || "(no name)"}</strong> {row.values.email ? `· ${row.values.email}` : ""}
                {!row.isValid && <span className="muted"> — {row.reasons.join("; ")}</span>}
              </div>
            ))}
          </div>

          <div className="row">
            <button className="btn" onClick={() => setState("paste")}>Back</button>
            <button className="btn btn-primary" onClick={commit}>Import valid rows</button>
          </div>
        </>
      )}
    </div>
  );
}import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getApiUser, handleError, ok, readJson, unauthorized } from "@/lib/api";
import { leadCreateSchema } from "@/lib/validation";
import { mapLead } from "@/lib/serialize";

export async function GET(req: Request) {
  try {
    const user = await getApiUser();
    if (!user) return unauthorized();
    const url = new URL(req.url);
    const status = url.searchParams.get("status");
    const q = (url.searchParams.get("q") ?? "").toLowerCase();
    const tier = url.searchParams.get("tier"); // HOT | WARM | COLD

    const leads = await prisma.lead.findMany({
      where: {
        userId: user.id,
        ...(status ? { status } : {}),
        ...(q
          ? {
              OR: [
                { name: { contains: q } },
                { companyOrChannel: { contains: q } },
                { email: { contains: q } },
                { niche: { contains: q } },
              ],
            }
          : {}),
      },
      orderBy: [{ leadScore: "desc" }, { createdAt: "desc" }],
      include: {
        _count: { select: { emails: true, replies: true, followUps: true } },
      },
    });

    const filtered = tier
      ? leads.filter((l) => {
          if (tier === "HOT") return l.leadScore >= 80;
          if (tier === "WARM") return l.leadScore >= 50 && l.leadScore < 80;
          return l.leadScore < 50;
        })
      : leads;

    return ok({ leads: filtered.map(mapLead) });
  } catch (err) {
    return handleError(err);
  }
}

export async function POST(req: Request) {
  try {
    const user = await getApiUser();
    if (!user) return unauthorized();
    const body = await readJson(req);
    const d = leadCreateSchema.parse(body);

    const email = d.email?.toLowerCase().trim() || null;
    if (email) {
      const dup = await prisma.lead.findUnique({
        where: { userId_email: { userId: user.id, email } },
      });
      if (dup) {
        return NextResponse.json(
          { error: `A lead with email ${email} already exists` },
          { status: 409 },
        );
      }
    }

    const lead = await prisma.lead.create({
      data: {
        userId: user.id,
        name: d.name,
        companyOrChannel: d.companyOrChannel,
        email,
        websiteUrl: d.websiteUrl,
        youtubeUrl: d.youtubeUrl,
        instagramUrl: d.instagramUrl,
        telegramUrl: d.telegramUrl,
        niche: d.niche,
        followersCount: d.followersCount,
        contentActivity: d.contentActivity,
        longFormCount: d.longFormCount,
        shortFormCount: d.shortFormCount,
        growthSignal: d.growthSignal,
        commercialPotential: d.commercialPotential,
        status: "New",
      },
    });

    await prisma.activity.create({
      data: { userId: user.id, leadId: lead.id, type: "LeadCreated", payload: JSON.stringify({}) },
    });

    return ok({ lead: mapLead(lead) }, 201);
  } catch (err) {
    return handleError(err);
  }
}

