--- shell/css/dashboard/settings ---
:root {
  --bg: #ffffff;
  --bg-subtle: #fafafa;
  --surface: #ffffff;
  --surface-2: #f6f6f7;
  --border: #ececee;
  --border-strong: #e2e2e5;
  --text: #17171a;
  --text-muted: #6f6f76;
  --text-faint: #9a9aa2;
  --accent: #ff5c1f;
  --accent-strong: #e6490f;
  --green: #16a34a;
  --green-bg: #e9f8ef;
  --red: #dc2626;
  --red-bg: #fdeceb;
  --amber: #d97706;
  --amber-bg: #fdf3e3;
  --blue: #2563eb;
  --blue-bg: #eaf1fd;
  --gray-bg: #f1f1f3;
  --shadow-sm: 0 1px 2px rgba(16, 16, 20, 0.04);
  --shadow-md: 0 4px 16px rgba(16, 16, 20, 0.08);
  --radius: 12px;
  --radius-sm: 8px;
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e0e11;
    --bg-subtle: #111115;
    --surface: #15151a;
    --surface-2: #1c1c22;
    --border: #26262d;
    --border-strong: #33333c;
    --text: #ededf0;
    --text-muted: #a1a1aa;
    --text-faint: #6f6f78;
    --accent: #ff6a33;
    --accent-strong: #ff7a48;
    --green: #34d377;
    --green-bg: #15301f;
    --red: #ff6b6b;
    --red-bg: #351b1b;
    --amber: #f5b04c;
    --amber-bg: #332a17;
    --blue: #6ca3ff;
    --blue-bg: #16233b;
    --gray-bg: #202024;
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.45);
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  padding: 0;
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

h1,
h2,
h3 {
  margin: 0;
  font-weight: 650;
  letter-spacing: -0.01em;
}

button {
  font-family: inherit;
}

/* Layout */
.app-shell {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  width: 220px;
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  padding: 16px 12px;
  position: sticky;
  top: 0;
  height: 100vh;
  background: var(--bg-subtle);
}

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 16px;
  padding: 4px 8px 16px;
}

.sidebar-brand .mark {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: linear-gradient(135deg, var(--accent), #ffb37a);
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  color: var(--text-muted);
  font-weight: 500;
  margin-bottom: 2px;
}

.nav-link:hover {
  background: var(--surface-2);
  color: var(--text);
}

.nav-link.active {
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}

.sidebar-footer {
  position: absolute;
  bottom: 16px;
  left: 12px;
  right: 12px;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

.main {
  flex: 1;
  padding: 32px 40px;
  max-width: 1100px;
}

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}

.page-title {
  font-size: 22px;
}

.page-sub {
  color: var(--text-muted);
  font-size: 14px;
  margin-top: 4px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 550;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, opacity 0.12s;
  white-space: nowrap;
}

.btn:hover { background: var(--surface-2); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-strong); }
.btn-danger { background: var(--red); border-color: var(--red); color: #fff; }
.btn-ghost-danger { background: transparent; border-color: transparent; color: var(--red); }
.btn-sm { padding: 5px 10px; font-size: 13px; }
.btn-lg { padding: 11px 18px; font-size: 15px; }

/* Cards & tables */
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-sm); }

.metric-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-bottom: 28px; }

.metric { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; }
.metric .label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.metric .value { font-size: 26px; font-weight: 700; margin-top: 4px; letter-spacing: -0.02em; }

.data-table { width: 100%; border-collapse: collapse; }
.data-table th { text-align: left; font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; padding: 10px 12px; border-bottom: 1px solid var(--border); }
.data-table td { padding: 12px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.data-table tbody tr:hover { background: var(--bg-subtle); }

/* Forms */
.field { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }
.field label { font-size: 13px; font-weight: 550; color: var(--text-muted); }
.input, .select, textarea.input { border: 1px solid var(--border-strong); background: var(--surface); color: var(--text); border-radius: var(--radius-sm); padding: 9px 12px; font-size: 14px; font-family: inherit; width: 100%; }
.input:focus, .select:focus, textarea.input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(255, 92, 31, 0.15); }
textarea.input { resize: vertical; min-height: 120px; line-height: 1.6; }

/* Badges */
.badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 600; }
.badge.hot { background: var(--red-bg); color: var(--red); }
.badge.warm { background: var(--amber-bg); color: var(--amber); }
.badge.cold { background: var(--gray-bg); color: var(--text-muted); }
.badge.green { background: var(--green-bg); color: var(--green); }
.badge.blue { background: var(--blue-bg); color: var(--blue); }
.badge.gray { background: var(--gray-bg); color: var(--text-muted); }

/* Generic */
.row { display: flex; align-items: center; gap: 12px; }
.grow { flex: 1; }
.muted { color: var(--text-muted); }
.small { font-size: 13px; }
.stack { display: flex; flex-direction: column; gap: 8px; }
.section-label { font-size: 13px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; margin-bottom: 8px; }

.split { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; align-items: start; }

@media (max-width: 900px) {
  .split { grid-template-columns: 1fr; }
  .main { padding: 20px; }
}

.toast { position: fixed; bottom: 20px; right: 20px; background: var(--text); color: var(--bg); padding: 12px 16px; border-radius: 10px; box-shadow: var(--shadow-md); font-size: 14px; z-index: 50; max-width: 320px; }
.toast.error { background: var(--red); color: #fff; }

.spinner { width: 14px; height: 14px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: spin 0.7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.empty { padding: 40px; text-align: center; color: var(--text-muted); }
.insight-box { border-left: 3px solid var(--accent); background: var(--surface-2); padding: 12px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; font-size: 14px; }
.mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; white-space: pre-wrap; }
.divider { height: 1px; background: var(--border); margin: 16px 0; }import type { Metadata } from "next";
import "./globals.css";
import { getCurrentUser } from "@/lib/auth";
import { Shell } from "@/components/Shell";

export const metadata: Metadata = {
  title: "ClipReach — персональные рассылки",
  description: "Рабочее пространство для персонализированных писем и работы с лидами.",
};

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const user = await getCurrentUser();

  return (
    <html lang="ru">
      <body>
        {user ? (
          <Shell email={user.email} initialPaused={user.outreachPaused}>
            {children}
          </Shell>
        ) : (
          children
        )}
      </body>
    </html>
  );
}"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { api } from "@/lib/client";
import { normalizeDashboard, type Dashboard } from "@/lib/dashboard";
import { formatDate } from "@/lib/utils";

export default function HomePage() {
  const [data, setData] = useState<Dashboard | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;
    setError("");
    api<unknown>("/api/dashboard")
      .then((response) => {
        if (active) setData(normalizeDashboard(response));
      })
      .catch((e) => {
        if (active) setError(e instanceof Error ? e.message : "Не удалось загрузить данные");
      });
    return () => {
      active = false;
    };
  }, []);

  if (error) return <div className="empty">{error}</div>;
  if (!data) return <div className="empty">Загрузка главной страницы…</div>;

  const c = data.counters;

  return (
    <div>
      <div className="page-head">
        <div>
          <h1 className="page-title">Главная</h1>
          <p className="page-sub">
            {c.pendingFollowUps === 0
              ? "Все задачи выполнены — на сегодня повторных контактов нет."
              : `На сегодня запланировано повторных контактов: ${c.pendingFollowUps}.`}
          </p>
        </div>
        <Link href="/leads/new" className="btn btn-primary">+ Добавить лида</Link>
      </div>

      <div className="metric-grid">
        <Metric label="Всего лидов" value={c.totalLeads} />
        <Metric label="Новые" value={c.newLeads} />
        <Metric label="Квалифицированы" value={c.qualified} />
        <Metric label="Писем отправлено" value={c.emailsSent} />
        <Metric label="Ответы" value={c.replies} />
        <Metric label="Доля ответов" value={`${c.replyRate}%`} />
        <Metric label="Клиенты" value={c.clients} />
      </div>

      <div className="split">
        <section>
          <div className="section-label">Горячие лиды</div>
          <div className="card">
            {data.hotLeads.length === 0 ? (
              <div className="empty">Лидов пока нет. Добавьте или импортируйте первых потенциальных клиентов.</div>
            ) : (
              data.hotLeads.map((l, i) => (
                <Link key={l.id} href={`/leads/${l.id}`} className="row" style={{ padding: "12px 16px", borderBottom: i < data.hotLeads.length - 1 ? "1px solid var(--border)" : "none" }}>
                  <span className="grow" style={{ fontWeight: 550 }}>{l.name}</span>
                  <span className={`badge ${l.leadScore >= 80 ? "hot" : l.leadScore >= 50 ? "warm" : "cold"}`}>
                    {l.leadScore}
                  </span>
                </Link>
              ))
            )}
          </div>
        </section>

        <section>
          <div className="section-label">Повторные контакты на сегодня</div>
          <div className="card">
            {data.dueFollowUps.length === 0 ? (
              <div className="empty">На сегодня повторных контактов нет.</div>
            ) : (
              data.dueFollowUps.map((f, i) => (
                <Link key={f.id} href={`/leads/${f.lead.id}`} className="row" style={{ padding: "12px 16px", borderBottom: i < data.dueFollowUps.length - 1 ? "1px solid var(--border)" : "none" }}>
                  <div className="grow">
                    <div style={{ fontWeight: 550 }}>{f.lead.name}</div>
                    <div className="small muted">{f.lead.companyOrChannel || ""}</div>
                  </div>
                  <div className="small muted">срок: {formatDate(f.dueDate)}</div>
                </Link>
              ))
            )}
          </div>
        </section>
      </div>

      <div className="divider" />
      <section>
        <div className="section-label">Recent replies</div>
        <div className="card">
          {data.recentReplies.length === 0 ? (
            <div className="empty">No replies yet. They&apos;ll show up here as soon as someone responds.</div>
          ) : (
            data.recentReplies.map((r, i) => (
              <div key={r.id} className="row" style={{ padding: "12px 16px", borderBottom: i < data.recentReplies.length - 1 ? "1px solid var(--border)" : "none" }}>
                <div className="grow" style={{ fontWeight: 550 }}>
                  {r.lead.name}
                  <span className="small muted" style={{ marginLeft: 8 }}>· {formatDate(r.receivedAt)}</span>
                </div>
                <span className="badge green">{r.classification}</span>
              </div>
            ))
          )}
        </div>
      </section>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="metric">
      <div className="label">{label}</div>
      <div className="value">{value}</div>
    </div>
  );
}"use client";

import { useCallback, useEffect, useState } from "react";
import { api } from "@/lib/client";

type Provider = {
  id: string;
  kind: string;
  platform?: string;
  isActive: boolean;
  dailyLimit: number;
  configured?: boolean;
  safeConfig?: { host?: string; port?: number; user?: string; from?: string; model?: string };
  createdAt: string;
};
type Suppression = { id: string; email: string; reason: string; createdAt: string };

export default function SettingsPage() {
  const [paused, setPaused] = useState(false);
  const [providers, setProviders] = useState<Provider[]>([]);
  const [suppressions, setSuppressions] = useState<Suppression[]>([]);
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [savingKind, setSavingKind] = useState<"email" | "ai" | null>(null);

  const load = useCallback(async () => {
    try {
      const [me, prov, sup] = await Promise.all([
        api<{ user: { outreachPaused: boolean } }>("/api/auth/me"),
        api<{ providers: Provider[] }>("/api/settings/providers"),
        api<{ entries: Suppression[] }>("/api/suppressions"),
      ]);
      setPaused(me.user.outreachPaused);
      setProviders(prov.providers);
      console.info("[settings] providers loaded", prov.providers.map((p) => ({ id: p.id, kind: p.kind, configured: p.configured, isActive: p.isActive })));
      setSuppressions(sup.entries);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Не удалось загрузить данные");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const togglePause = async () => {
    const next = !paused;
    await api("/api/settings/pause", { method: "POST", body: JSON.stringify({ paused: next }) });
    setPaused(next);
  };

  const removeProvider = async (id: string) => {
    try {
      setError("");
      await api(`/api/settings/providers?id=${id}`, { method: "DELETE" });
      setNotice("Провайдер удалён.");
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Не удалось удалить провайдера");
    }
  };

  const addSuppression = async (email: string) => {
    await api("/api/suppressions", { method: "POST", body: JSON.stringify({ email, reason: "ManualBlock" }) });
    load();
  };

  const removeSuppression = async (id: string) => {
    await api(`/api/suppressions?id=${id}`, { method: "DELETE" });
    load();
  };

  const saveProvider = async (body: Record<string, unknown>) => {
    const kind = body.type === "email" ? "email" : "ai";
    setSavingKind(kind);
    setNotice("");
    setError("");
    try {
      const response = await api<{ provider: Provider }>("/api/settings/providers", {
        method: "POST",
        body: JSON.stringify(body),
      });
      setProviders((current) => {
        const saved = response.provider;
        return [saved, ...current.filter((p) => !(p.kind === saved.kind && p.id !== saved.id))];
      });
      await load();
      setNotice("Провайдер сохранён.");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Не удалось сохранить");
    } finally {
      setSavingKind(null);
    }
  };

  return (
    <div>
      <div className="page-head">
        <div>
          <h1 className="page-title">Настройки</h1>
          <p className="page-sub">Подключение провайдеров и безопасное управление рассылкой.</p>
        </div>
      </div>

      {notice && <div className="card" style={{ padding: 12, marginBottom: 16, borderColor: "var(--green)", color: "var(--green)" }}>{notice}</div>}
      {error && <div className="card" style={{ padding: 12, marginBottom: 16, borderColor: "var(--red)", color: "var(--red)" }}>{error}</div>}
      {loading && <div className="card empty">Загрузка настроек…</div>}

      {!loading && <div className="stack" style={{ gap: 20 }}>
        <section className="card" style={{ padding: 18 }}>
          <div className="row">
            <div className="grow">
              <strong>Global pause</strong>
              <div className="small muted">Immediately stop placing new emails for sending.</div>
            </div>
            <button className={`btn ${paused ? "" : "btn-danger"}`} onClick={togglePause}>
              {paused ? "▶ Resume outreach" : "⏹ STOP ALL OUTREACH"}
            </button>
            <span className={`badge ${paused ? "red" : "green"}`}>{paused ? "Paused" : "Active"}</span>
          </div>
        </section>

        <ProviderPane label="Почтовый провайдер" providers={providers.filter((p) => p.kind === "email")} onRemove={removeProvider}>
          <EmailForm onSave={saveProvider} saving={savingKind === "email"} savedProvider={providers.find((p) => p.kind === "email" && p.isActive)} />
        </ProviderPane>

        <ProviderPane label="AI-провайдер" providers={providers.filter((p) => p.kind === "ai")} onRemove={removeProvider}>
          <AiForm onSave={saveProvider} saving={savingKind === "ai"} savedProvider={providers.find((p) => p.kind === "ai" && p.isActive)} />
        </ProviderPane>

        <section className="card" style={{ padding: 18 }}>
          <div className="section-label">Suppression list</div>
          <p className="small muted" style={{ marginTop: 0 }}>
            Emails here can never receive outbound mail from you (hard gate on the API). Unsubscribe and hard
            bounces land here automatically.
          </p>
          <AddEmail onAdd={addSuppression} />
          <div className="stack" style={{ marginTop: 12 }}>
            {suppressions.length === 0 ? (
              <div className="small muted">No suppressed addresses.</div>
            ) : (
              suppressions.map((s) => (
                <div key={s.id} className="row">
                  <span className="grow">{s.email}</span>
                  <span className={`badge ${s.reason === "Unsubscribed" ? "red" : "gray"}`}>{s.reason}</span>
                  <button className="btn btn-sm btn-ghost-danger" onClick={() => removeSuppression(s.id)}>Remove</button>
                </div>
              ))
            )}
          </div>
        </section>
      </div>}
    </div>
  );
}

function ProviderPane({ label, providers, onRemove, children }: {
  label: string; providers: Provider[]; onRemove: (id: string) => void; children: React.ReactNode;
}) {
  return (
    <section className="card" style={{ padding: 18 }}>
      <div className="section-label">{label}</div>
      <div className="stack" style={{ marginBottom: 12 }}>
        {providers.length === 0 ? (
          <div className="small muted">Not connected. Configure a provider before using this feature.</div>
        ) : (
          providers.map((p, index) => (
            <div key={`${p.kind}-${p.id}-${index}`} className="row">
              <span className="grow">Provider {p.isActive && <span className="badge green">active</span>}</span>
              <span className="small muted">limit {p.dailyLimit}/day</span>
              <button className="btn btn-sm btn-ghost-danger" onClick={() => onRemove(p.id)}>Remove</button>
            </div>
          ))
        )}
      </div>
      {children}
    </section>
  );
}
function EmailForm({ onSave, saving, savedProvider }: { onSave: (b: Record<string, unknown>) => void; saving: boolean; savedProvider?: Provider }) {
  const [form, setForm] = useState({ host: "smtp.gmail.com", port: "587", user: "", pass: "", from: "" });
  useEffect(() => {
    if (!savedProvider?.safeConfig) return;
    setForm((current) => ({ ...current, host: savedProvider.safeConfig?.host ?? current.host, port: String(savedProvider.safeConfig?.port ?? current.port), user: savedProvider.safeConfig?.user ?? current.user, from: savedProvider.safeConfig?.from ?? current.from, pass: "" }));
  }, [savedProvider]);
  const set = (k: keyof typeof form) => (e: { target: { value: string } }) => setForm((f) => ({ ...f, [k]: e.target.value }));

  return (
    <form className="card" style={{ background: "var(--surface-2)", padding: 14 }} onSubmit={(e) => {
      e.preventDefault();
      onSave({
        type: "email",
        platform: "SMTP",
        config: JSON.stringify({ type: "SMTP", host: form.host, port: Number(form.port), secure: form.port === "465", user: form.user, pass: form.pass, from: form.from }),
        dailyLimit: 25,
      });
    }}>
      <div className="row">
        <div className="field grow"><label>Host</label><input className="input" value={form.host} onChange={set("host")} placeholder="smtp.example.com" required /></div>
        <div className="field" style={{ width: 90 }}><label>Port</label><input className="input" value={form.port} onChange={set("port")} /></div>
      </div>
      <div className="row">
        <div className="field grow"><label>Username</label><input className="input" value={form.user} onChange={set("user")} required /></div>
        <div className="field grow"><label>Password</label><input className="input" type="password" value={form.pass} onChange={set("pass")} required={!savedProvider?.configured} placeholder={savedProvider?.configured ? "Сохранённый пароль защищён; оставьте пустым, чтобы не менять" : "App password"} /></div>
      </div>
      <div className="field"><label>From address</label><input className="input" value={form.from} onChange={set("from")} placeholder="you@example.com" /></div>
      {savedProvider?.configured && <div className="small" style={{ color: "var(--green)", marginBottom: 8 }}>SMTP is configured. Secret fields stay blank for security.</div>}
      <button className="btn btn-primary" type="submit" disabled={saving}>{saving ? "Saving…" : savedProvider ? "Update SMTP provider" : "Save SMTP provider"}</button>
    </form>
  );
}

function AiForm({ onSave, saving, savedProvider }: { onSave: (b: Record<string, unknown>) => void; saving: boolean; savedProvider?: Provider }) {
  const hasSavedProvider = Boolean(savedProvider?.configured);
  type Model = { id: string; name: string; provider: string; contextLength: number | null; isFree: boolean; status: string };
  const [platform, setPlatform] = useState("OpenAI");
  const [apiKey, setApiKey] = useState("");
  const [model, setModel] = useState("");
  useEffect(() => {
    if (!savedProvider?.safeConfig) return;
    setModel(savedProvider.safeConfig.model ?? "");
    if (savedProvider.platform) setPlatform(savedProvider.platform);
  }, [savedProvider]);
  const [models, setModels] = useState<Model[]>([]);
  const [freeOnly, setFreeOnly] = useState(true);
  const [testing, setTesting] = useState(false);
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (platform !== "OpenRouter") return;
    api<{ models: Model[]; fallback: boolean }>(`/api/settings/ai-models?freeOnly=${freeOnly}`)
      .then((data) => { setModels(data.models); setMessage(data.fallback ? "OpenRouter недоступен: показан резервный список." : ""); })
      .catch((e) => setMessage(e instanceof Error ? e.message : "Не удалось загрузить модели"));
  }, [platform, freeOnly]);

  const testConnection = async () => {
    setTesting(true);
    try {
      const result = await api<{ message: string }>("/api/settings/test-connection", {
        method: "POST", body: JSON.stringify({ platform, apiKey, model }),
      });
      setMessage(result.message);
    } catch (e) { setMessage(e instanceof Error ? e.message : "Проверка не удалась"); }
    finally { setTesting(false); }
  };

  return (
    <form className="card" style={{ background: "var(--surface-2)", padding: 14 }} onSubmit={(e) => {
      e.preventDefault();
      if (hasSavedProvider && !apiKey) {
        onSave({ type: "ai", platform, config: JSON.stringify({ platform }), dailyLimit: 50 });
        return;
      }
      onSave({ type: "ai", platform, config: JSON.stringify({ platform, apiKey, model }), dailyLimit: 50 });
    }}>
      <div className="field"><label>AI-провайдер</label>
        <select className="select" value={platform} onChange={(e) => { setPlatform(e.target.value); setModel(""); }}>
          <option value="OpenAI">OpenAI</option>
          <option value="OpenRouter">OpenRouter</option>

